package com.lexiscan.admin; import com.lexiscan.analysis.*; import com.lexiscan.document.DocumentRepository; import com.lexiscan.user.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {final UserRepository users;final DocumentRepository docs;final RiskRuleRepository rules;public AdminController(UserRepository u,DocumentRepository d,RiskRuleRepository r){users=u;docs=d;rules=r;} record UserView(UUID id,String name,String email,Role role,boolean enabled){} record Status(boolean enabled){} @GetMapping("/users") List<UserView> users(){return users.findAll().stream().map(u->new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole(),u.isEnabled())).toList();}@PatchMapping("/users/{id}/status") UserView status(@PathVariable UUID id,@RequestBody Status s){var u=users.findById(id).orElseThrow();u.setEnabled(s.enabled());users.save(u);return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole(),u.isEnabled());}@GetMapping("/stats") Map<String,Object> stats(){return Map.of("totalUsers",users.count(),"totalDocuments",docs.count(),"analyses",docs.countByStatus(com.lexiscan.document.DocumentStatus.ANALYZED));}@GetMapping("/rules") List<RiskRule> rules(){return rules.findAll();}@PostMapping("/rules") @ResponseStatus(HttpStatus.CREATED) RiskRule add(@RequestBody RiskRule r){r.setId(UUID.randomUUID());return rules.save(r);}@PutMapping("/rules/{id}") RiskRule edit(@PathVariable UUID id,@RequestBody RiskRule r){r.setId(id);return rules.save(r);}@PatchMapping("/rules/{id}") RiskRule toggle(@PathVariable UUID id,@RequestBody Status s){var r=rules.findById(id).orElseThrow();r.setActive(s.enabled());return rules.save(r);} }
